/**
 * =============================================================================
 * FILE: src/components/GettingStartedTour.jsx
 * VERSION: v3
 * =============================================================================
 * PURPOSE
 *   Shows the getting-started tour (public/guide/tour.html — slides with real
 *   screenshots and an Everyday / Owner path choice) in a full-screen layer
 *   over the dashboard.
 *
 * HOW THE TOUR STAYS CURRENT
 *   tour.html and its screenshots are generated by guides/run.py, which
 *   GitHub Actions re-runs on every update. This component never hardcodes
 *   slide content; it only loads the page.
 *
 * WHEN IT OPENS
 *   Decided by hooks/useOnboarding.js (first sign-in on an account) or by
 *   ⋮ › Getting started tour. Remembering that it was seen is also that
 *   hook's job (per account, not per device), so this component just shows
 *   the tour and reports when it closes.
 *
 * CLOSING
 *   The tour page posts {type:'tour:close'} to this window (same origin)
 *   when its Close / Done buttons are tapped; Escape inside it does too.
 *   "Open the full guide" posts the same message with an href: the layer
 *   closes and this window opens the guide (same-origin URLs only).
 *
 * REVISION HISTORY
 *   v1  2026-11-18  Initial: overlay, auto-open, seen marker.
 *   v2  2026-11-18  Focus the tour on load; "Open the full guide" closes the
 *                   layer and opens the guide in this window.
 *   v3  2026-11-20  Auto-open and the seen marker moved to useOnboarding
 *                   (per account, role-aware What's new card). The tour's
 *                   own What's new screen is no longer opened directly.
 * =============================================================================
 */

import { useEffect } from 'react'

const TOUR_URL = '/guide/tour.html'

/**
 * Full-screen tour layer.
 * @param {object} props
 * @param {() => void} props.onClose - called when the tour asks to close.
 */
export default function GettingStartedTour({ onClose }) {
  useEffect(() => {
    function onMessage(e) {
      if (e.origin !== window.location.origin || e.data?.type !== 'tour:close') return
      onClose()
      // "Open the full guide" from inside the tour: go there in this window
      // (only same-origin pages, so a message can't send us elsewhere).
      if (typeof e.data.href === 'string') {
        try {
          const dest = new URL(e.data.href, window.location.href)
          if (dest.origin === window.location.origin) window.location.assign(dest.href)
        } catch { /* bad URL: just close */ }
      }
    }
    window.addEventListener('message', onMessage)
    return () => window.removeEventListener('message', onMessage)
  }, [onClose])

  return (
    <div
      className="fixed inset-0 z-[90] bg-[var(--color-ink)]"
      style={{
        paddingTop: 'env(safe-area-inset-top)',
        paddingBottom: 'env(safe-area-inset-bottom)',
        paddingLeft: 'env(safe-area-inset-left)',
        paddingRight: 'env(safe-area-inset-right)',
      }}
      role="dialog"
      aria-modal="true"
      aria-label="Getting started tour"
    >
      <iframe
        src={TOUR_URL}
        title="Getting started tour"
        className="w-full h-full border-0 block"
        // Focus the tour once loaded so its keyboard shortcuts (Escape to
        // close, arrow keys to step) work without clicking into it first.
        onLoad={(e) => { try { e.currentTarget.contentWindow.focus() } catch { /* same origin; ignore */ } }}
      />
    </div>
  )
}
